"""Write a venv sitecustomize that shims blocked native wheels before imports."""

from __future__ import annotations

import sys
from pathlib import Path

_CONTENT = """\
# Auto-generated by scripts/install_native_wheel_sitecustomize.py — do not edit.
try:
    from backend.native_wheel_compat import ensure_native_wheel_shims

    ensure_native_wheel_shims()
except Exception:
    pass
"""


def main() -> int:
    if len(sys.path) < 1:
        return 1
    # site-packages is typically .../Lib/site-packages on Windows.
    candidates = [Path(p) for p in sys.path if p.endswith("site-packages")]
    if not candidates:
        print("no site-packages on sys.path; skip sitecustomize install", file=sys.stderr)
        return 0
    target = candidates[0] / "sitecustomize.py"
    target.write_text(_CONTENT, encoding="utf-8")
    print(f"wrote {target}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
